"""Randomised exact verification of the rank-two packing/covering theorems.

For pseudo-random integral binary forms this script:

  1. reduces the form by Gauss reduction and checks that the leading coefficient equals
     the homogeneous minimum found by exhaustive search;
  2. checks the closed formula for the covering radius against an exhaustive search for
     the deepest point of a fine rational grid, and against the exact value of the gap
     at the predicted deep hole;
  3. checks the strictness identity mu - lambda_1/4 = a(2c-b)^2/(4D);
  4. checks the sharp inequality mu >= lambda_1/3 with equality only for the hexagonal
     form, and the rectangularity criterion (a half-point is a deepest hole iff b = 0);
  5. checks the three-torsion certificate for the hexagonal lattice: every half-point of
     x^2+xy+y^2 has gap exactly 1/4, while (1/3, 1/3) has gap 1/3.

All arithmetic is exact (fractions.Fraction); no floating point is used anywhere.
"""

from __future__ import annotations

import random
from fractions import Fraction
from itertools import product
from typing import Tuple

Rat = Fraction


def gauss_reduce(a: Rat, b: Rat, c: Rat) -> Tuple[Rat, Rat, Rat]:
    while True:
        if c < a:
            a, c = c, a
        if abs(b) > a:
            k = -round(Fraction(b, 2 * a))
            c = a * k * k + b * k + c
            b = b + 2 * k * a
            continue
        break
    return (a, -b, c) if b < 0 else (a, b, c)


def value(a: Rat, b: Rat, c: Rat, x: Rat, y: Rat) -> Rat:
    return a * x * x + b * x * y + c * y * y


def minimum(a: Rat, b: Rat, c: Rat, bound: int = 6) -> Rat:
    return min(value(a, b, c, Rat(p), Rat(q))
               for p, q in product(range(-bound, bound + 1), repeat=2)
               if (p, q) != (0, 0))


def gap(a: Rat, b: Rat, c: Rat, t: Tuple[Rat, Rat], bound: int = 4) -> Rat:
    return min(value(a, b, c, t[0] - p, t[1] - q)
               for p, q in product(range(-bound, bound + 1), repeat=2))


def cover_radius(a: Rat, b: Rat, c: Rat) -> Rat:
    return a * c * (a - b + c) / (4 * a * c - b * b)


def deep_hole(a: Rat, b: Rat, c: Rat) -> Tuple[Rat, Rat]:
    d = 4 * a * c - b * b
    return c * (2 * a - b) / d, a * (2 * c - b) / d


def main(trials: int = 24, seed: int = 20260811) -> None:
    rng = random.Random(seed)
    print(f"{'form':>18} {'reduced':>14} {'lambda_1':>8} {'mu':>12} {'mu/l1':>8}  checks")
    failures = 0
    for _ in range(trials):
        while True:
            a0 = rng.randint(1, 9)
            c0 = rng.randint(1, 9)
            b0 = rng.randint(-9, 9)
            if 4 * a0 * c0 - b0 * b0 > 0:
                break
        a, b, c = gauss_reduce(Rat(a0), Rat(b0), Rat(c0))
        lam = minimum(a, b, c)
        mu = cover_radius(a, b, c)
        h = deep_hole(a, b, c)
        d = 4 * a * c - b * b

        ok_min = (lam == a)
        ok_hole = (gap(a, b, c, h) == mu)
        ok_grid = all(gap(a, b, c, (Rat(i, 12), Rat(j, 12))) <= mu
                      for i in range(12) for j in range(12))
        ok_excess = (mu - a / 4 == a * (2 * c - b) ** 2 / (4 * d))
        ok_third = (mu >= a / 3) and ((mu == a / 3) == (a == b == c))
        ok_rect = ((mu == (a - b + c) / 4) == (b == 0))
        good = all([ok_min, ok_hole, ok_grid, ok_excess, ok_third, ok_rect])
        failures += (not good)
        flags = "".join(s for s, ok in
                        [("min", ok_min), ("hole", ok_hole), ("grid", ok_grid),
                         ("excess", ok_excess), ("1/3", ok_third), ("rect", ok_rect)]
                        if not ok)
        print(f"({a0:>2},{b0:>3},{c0:>2})".rjust(18)
              + f" ({a},{b},{c})".rjust(15)
              + f" {str(lam):>8} {str(mu):>12} {str(mu/lam):>8}  "
              + ("all pass" if good else "FAIL: " + flags))

    print(f"\n{trials - failures}/{trials} random forms passed every check.")

    print("\nHexagonal lattice x^2+xy+y^2: the two-torsion certificate fails.")
    A = (Rat(1), Rat(1), Rat(1))
    for v in [(0, 1), (1, 0), (1, 1)]:
        print(f"  gap at half-point {v[0]}/2,{v[1]}/2 = "
              f"{gap(*A, (Rat(v[0], 2), Rat(v[1], 2)))}   (= lambda_1/4)")
    print(f"  gap at the third-point (1/3,1/3) = {gap(*A, (Rat(1,3), Rat(1,3)))}"
          f"   (= mu = {cover_radius(*A)})")
    print("  reason: X = Y = 1 (mod 3) forces 3 | X^2+XY+Y^2, hence X^2+XY+Y^2 >= 3.")


if __name__ == "__main__":
    main()
